mapper.select:
SELECT t.id, t.mix_area, t.material, p.stock_num, t.safe_stock, t.remark, t.del_flag, t.create_by, t.create_time, t.update_by, t.update_time FROM t_lhfl_safe_stock t LEFT JOIN (SELECT MIX_AREA, MATERIAL_NAME MATERIAL, STOCK_DATE, SUM(ifnull(STOCK_NUM, 0)) STOCK_NUM FROM T_LHFL_GLUE_STOCK WHERE DEL_FLAG = '0' GROUP BY MIX_AREA, MATERIAL_NAME, STOCK_DATE) p ON p.STOCK_DATE = #{todayDate,jdbcType=TIMESTAMP} AND t.MATERIAL = p.MATERIAL AND t.MIX_AREA = p.MIX_AREA WHERE t.del_flag = '0' and t.mix_area = #{mixArea} and INSTR(t.material, #{material}) > 0
order by create_time desc
order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.mixArea,jdbcType=VARCHAR} MIX_AREA, #{data.material,jdbcType=VARCHAR} material
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from T_lhfl_SAFE_STOCK m inner join temp_table t on m.MIX_AREA = t.MIX_AREA and m.material = t.material and m.del_flag ='0'

mapper.insert:
insert into t_lhfl_safe_stock (id,mix_area,material,safe_stock,remark,del_flag,create_by,create_time,update_by,update_time ) select NULL id, x.* from (
select #{lhflSafeStock.mixArea,jdbcType=VARCHAR} mix_area, #{lhflSafeStock.material,jdbcType=VARCHAR} material, #{lhflSafeStock.safeStock,jdbcType=DOUBLE} safe_stock, #{lhflSafeStock.remark,jdbcType=VARCHAR} remark, #{lhflSafeStock.delFlag,jdbcType=VARCHAR} del_flag, #{lhflSafeStock.createBy,jdbcType=VARCHAR} create_by, #{lhflSafeStock.createTime,jdbcType=TIMESTAMP} create_time, #{lhflSafeStock.updateBy,jdbcType=VARCHAR} update_by, #{lhflSafeStock.updateTime,jdbcType=TIMESTAMP} update_time
) x
